# Standard library
import uuid

# Third-party
from sqlalchemy import ForeignKey, Integer, func
from sqlalchemy.orm import Mapped, mapped_column

# Local application
from app.core.base import Base, CreatorMixin, TimestampMixin


class ExplorerM2mSegmentPoi(TimestampMixin, CreatorMixin, Base):
    __tablename__ = "explorer_m2m_segment_poi"

    id: Mapped[uuid.UUID] = mapped_column(
        primary_key=True,
        server_default=func.gen_random_uuid(),
        description=(
            "Primary key UUID, auto-generated by the database using "
            "gen_random_uuid()."
        ),
    )
    slot_position: Mapped[int] = mapped_column(
        Integer,
        nullable=False,
        description=(
            "Zero-based ordering position of this POI along the segment."
        ),
    )
    segment_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("explorer_agg_segment.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "FK to explorer_agg_segment with CASCADE delete. The trail "
            "segment this POI is located along."
        ),
    )
    poi_id: Mapped[uuid.UUID] = mapped_column(
        ForeignKey("compendium_cat_poi.id", ondelete="CASCADE"),
        nullable=False,
        description=(
            "FK to compendium_cat_poi with CASCADE delete. The Point of "
            "Interest along this segment."
        ),
    )
    distance_m: Mapped[int | None] = mapped_column(
        Integer,
        description=("Distance in meters from the segment start to this POI."),
    )
